'use strict';
// Server mode is same-origin only. Hosted static mode keeps its separate browser workspace.
(async function(){
 if(!window.SENTINEL_SERVER_MODE)return;
 scoreURL=()=>{throw Error('This page requires server inference. Wait for the backend connection.')};
 let health;
 try{const response=await fetch('/api/health');if(!response.ok)throw Error('Backend health check failed');health=await response.json();if(health.scope!=='persistent-server')throw Error('Unexpected backend mode')}catch(e){for(const name of Object.keys(renders))renders[name]=()=>panel('Server unavailable','<div class="panel-body">Reconnect the backend and reload this page. Browser inference and recovery are disabled on this server page.</div>');document.querySelector('.header-right .pill').textContent='● Server unavailable';render();return}
 let server=null,serverError='',working=false,explanation=null;
 const browserBind=bind,browserAction=action,browserPredictions=renders.predictions,browserModels=renders.models;
 async function api(path,body,method='POST'){
  const response=await fetch('/api/'+path,{method:body===undefined?'GET':method,headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});
  const result=await response.json();if(!response.ok)throw Error(typeof result.detail==='string'?result.detail:JSON.stringify(result.detail));return result;
 }
 async function sync(){
  server=await api('state');serverError='';document.querySelector('.header-right .pill').textContent='● Persistent server';
  state.predictions=server.predictions;state.requests=server.requests;state.flagged=server.predictions.filter(p=>p.flag).length;
  state.events=server.events;state.champion=server.champion;state.candidate=server.candidate;state.previous=server.previous;
  state.settings={...server.settings,threshold:server.settings.threshold*100};
  state.ops={...server,auto:false};
 }
 async function run(fn){if(working)return;working=true;if(server)render();try{await fn();await sync()}catch(e){serverError=e.message;toast(e.message)}finally{working=false;render()}}
 // Browser writes must never overwrite the server state or local-mode history.
 save=function(){};
 trainCandidate=async function(){throw Error('Use the server recovery controls')};
 monitor=()=>server?.drift||{ready:false,count:0,features:[],status:'Connecting to server'};
 metricsHTML=()=>`<div class="metrics">${metric('URLs analyzed',server?.requests||0,'Saved in the server database','⌁')}${metric('Reviewed labels',server?.feedback.length||0,'Evidence and reviewer recorded','✓')}${metric('Distinct URLs in window',monitor().count,'30 required before PSI is reported','⌇')}${metric('Serving mode','Server','Persistent history · actual API','▧')}</div>`;
 decision=function(){if(!server)return {status:'Connecting',message:serverError||'Loading the persistent workspace',action:'Wait for connection'};const r=server.readiness,d=server.degradation;return {status:server.canary?'Canary running':server.candidate?'Candidate awaiting canary':d.confirmed?'Measured degradation':r.ok?'Ready for evaluation':'More reviewed labels needed',message:`${r.train} training / ${r.validation} validation labels. ${d.observed.n}/30 reviewed champion predictions. ${d.confirmed?'Error exceeds the recovery threshold.':'Automatic retraining needs confirmed errors; feature shift alone does not qualify.'}`,action:'Review recovery evidence'}};
 const summary=()=>`<div class="metrics">${metric('Reviewed labels',server.feedback.length,'Independent review attested','✓')}${metric('Observed error',server.degradation.observed.error===null?'—':percent(server.degradation.observed.error),`${server.degradation.observed.n} reviewed champion predictions`,'⌁')}${metric('Training / validation',`${server.readiness.train} / ${server.readiness.validation}`,'20 / 10 minimum; both classes in each','▤')}${metric('Degradation',server.degradation.confirmed?'Detected':'Not established','At least 30 reviewed predictions','⌇')}</div>`;
 function errorPanel(){return serverError?panel('Action needs attention',`<div class="panel-body error" role="alert">${esc(serverError)}</div>`):''}
 const toolsPanel=()=>panel('MLOps services on this computer',`<div class="panel-body"><div class="actions"><a class="button" href="/docs" target="_blank" rel="noopener">FastAPI documentation ↗</a><a class="button" href="http://localhost:5000" target="_blank" rel="noopener">MLflow experiments ↗</a><a class="button" href="http://localhost:3000/d/sentineldrift" target="_blank" rel="noopener">Grafana monitoring ↗</a><a class="button" href="http://localhost:9090/targets" target="_blank" rel="noopener">Prometheus targets ↗</a><a class="button" href="http://localhost:8080" target="_blank" rel="noopener">Airflow workflows ↗</a></div><p class="help">These links require the corresponding Docker services to be running. Airflow checks recovery every five minutes, including while this website is closed.</p></div>`);
 renders.predictions=()=>errorPanel()+browserPredictions().replace('Links are analyzed locally and never opened.','Links are analyzed by the local server and never opened.')+panel('Why did the model give this result?',`<div class="panel-body"><p>Calculate an approximate SHAP explanation for the latest saved prediction. Positive contributions increase the model score; negative contributions decrease it. This explains model behavior, not whether the website is safe.</p>${btn(working?'Working…':'Explain latest result','server-explain',false,!state.predictions.length||working)}${explanation?`<p>${esc(explanation.scope)}</p><p>Reference score ${(explanation.expected_value*100).toFixed(2)} + contributions → ${(explanation.score*100).toFixed(2)}/100.</p><div class="table-wrap"><table><thead><tr><th>Input</th><th>Measured value</th><th>Score contribution</th></tr></thead><tbody>${explanation.features.slice().sort((a,b)=>Math.abs(b.contribution)-Math.abs(a.contribution)).map(f=>`<tr><td>${esc(f.name)}</td><td>${f.value.toFixed(3)}</td><td>${f.contribution>=0?'+':''}${(f.contribution*100).toFixed(2)}</td></tr>`).join('')}</tbody></table></div>`:''}</div>`);
 renders.recovery=()=>!server?'<p>Connecting…</p>':head('PERSISTENT RECOVERY','Review. Train. Check. Deploy.','Real server training, MLflow evidence, guarded canary routing and reversible serving.',btn(working?'Working…':'Train & evaluate','server-train',true,working||!server.readiness.ok||!!server.candidate||!server.settings.enabled)+btn('Refresh','server-refresh'))+errorPanel()+summary()+panel('What happens next?',`<div class="panel-body"><h3>${decision().status}</h3><p>${decision().message}</p><p>Training learns an adaptive correction on the frozen classifier. It does not rebuild the Random Forest. Historical and recent validation checks must pass before a canary can begin.</p><a class="button" href="#data">Add checked labels →</a></div>`)+panel('Serving controls',`<div class="panel-body"><p>Champion: <strong>${esc(server.champion)}</strong></p><p>Candidate: ${esc(server.candidate||'None')}</p>${server.canary?`<p>${server.canary.weight}% candidate allocation · ${server.canary.requests} requests · ${server.canary.candidate_requests} actually served by candidate.</p><p>Fresh reviewed trial observations: ${server.canary_evidence.rows}/20. Promotion needs both classes and passing error checks; excess error can trigger rollback after 10.</p>`:''}<div class="actions">${btn('Start canary','server-canary',true,!server.candidate||!!server.canary||working)}${btn('Promote','server-promote',false,!server.canary_evidence?.pass||working)}${btn('Rollback','server-rollback',false,(!server.canary&&!server.previous)||working)}${btn('Discard candidate','server-discard',false,!server.candidate||!!server.canary||working)}${btn('Export evidence','server-export')}</div><p class="help">Small-sample prototype guardrails are not production statistical assurance.</p></div>`)+panel('Training and evaluation history',`<div class="panel-body">${server.jobs.length?server.jobs.map(j=>{const v=server.versions[j.id];return `<div class="result"><h3>${esc(j.id)} · ${esc(v?.status||j.status)}</h3><p>${esc(j.error||'')}${v?`Dataset SHA: ${esc(v.dataset_sha256)} · MLflow run: ${esc(v.mlflow_run_id)}`:''}</p>${v?v.evaluation.checks.map(c=>`<p>${c.pass?'✓':'✗'} ${esc(c.name)}: ${esc(c.detail)}</p>`).join(''):''}</div>`}).join(''):'No training jobs. Missing data is never replaced with invented labels.'}</div>`)+toolsPanel();
 renders.data=()=>!server?'<p>Connecting…</p>':head('REVIEWED FEEDBACK','Teach with checked answers.','Feedback is stored on the server. A reviewer and evidence reference are required.')+errorPanel()+panel('Review an analyzed URL',`<form id="server-review" class="panel-body"><div class="field"><label for="s-url">URL</label><input id="s-url" type="url" required value="${esc(state.predictions[0]?.url||'')}"></div><div class="field"><label for="s-label">Checked label</label><select id="s-label" required><option value="">Choose</option><option value="0">Legitimate</option><option value="1">Phishing</option></select></div><div class="field"><label for="s-evidence">Evidence / independent report reference</label><input id="s-evidence" required minlength="8" maxlength="500"></div><div class="field"><label for="s-reviewer">Reviewer name / ID</label><input id="s-reviewer" required minlength="2" maxlength="80"></div><p><label><input id="s-attest" type="checkbox" required> I independently checked this label; I did not copy the model's guess.</label></p><button class="button primary" ${working?'disabled':''}>Save checked label</button><p class="help">Reviewers are identified by their entered name; this local prototype does not authenticate them or verify external evidence.</p></form>`)+panel('Import reviewed CSV',`<form id="server-import" class="panel-body"><p>Required columns: url,label,evidence,reviewer. Labels: 0 legitimate, 1 phishing. Maximum 1 MB / 1,000 rows.</p><input id="s-file" type="file" accept=".csv" required><p><label><input id="s-import-attest" type="checkbox" required> These labels were independently reviewed.</label></p><button class="button" ${working?'disabled':''}>Import reviewed labels</button></form>`)+panel('Saved feedback',`<div class="table-wrap"><table><thead><tr><th>URL</th><th>Label</th><th>Partition</th><th>Reviewer / evidence</th></tr></thead><tbody>${server.feedback.slice(-100).reverse().map(r=>`<tr><td style="overflow-wrap:anywhere">${esc(r.url)}</td><td>${r.y?'Phishing':'Legitimate'}</td><td>${r.role}</td><td>${esc(r.reviewer)} · ${esc(r.evidence)}</td></tr>`).join('')}</tbody></table></div>`);
 renders.models=()=>errorPanel()+browserModels().replace('The multi-source baseline is serving. No adaptive correction has been promoted.','The multi-source baseline is serving. No adaptive correction has been promoted.')+toolsPanel();
 renders.settings=()=>!server?'<p>Connecting…</p>':head('SERVER POLICY','Control the recovery process.','Settings apply to the server workspace, not browser-local history.')+errorPanel()+panel('Recovery policy',`<form id="server-policy" class="panel-body"><div class="field"><label for="s-threshold">Strong-warning score threshold (90–99)</label><input id="s-threshold" type="number" min="90" max="99" value="${server.settings.threshold*100}" required></div><div class="field"><label for="s-share">Candidate share of real requests (1–50%)</label><input id="s-share" type="number" min="1" max="50" value="${server.settings.canary}" required></div><div class="field"><label for="s-cooldown">Minutes between training attempts</label><input id="s-cooldown" type="number" min="0" max="1440" value="${server.settings.cooldown}" required></div><p><label><input id="s-enabled" type="checkbox" ${server.settings.enabled?'checked':''}> Enable recovery</label></p><p><label><input id="s-auto" type="checkbox" ${server.settings.auto?'checked':''}> Automatic training, canary and promotion after evidence checks</label></p><button class="button primary">Save server policy</button><p class="help">Airflow must be running for unattended checks. Automatic safety rollback still applies when automatic training is disabled.</p></form>`)+toolsPanel();
 renders.incidents=()=>head('SERVER AUDIT','Recorded actions and outcomes.','Predictions, reviews, policy changes, training and deployment actions persist across restarts.')+panel('Audit history',`<div class="panel-body">${activity(100)}</div>`,btn('Export evidence','server-export'));
 action=function(name){const map={'server-train':'train','server-canary':'canary','server-promote':'promote','server-rollback':'rollback','server-discard':'discard'};if(map[name]){run(async()=>{const r=await api('recovery/'+map[name],{});if(r.reason)toast(r.reason)});return}if(name==='server-refresh'){run(async()=>{});return}if(name==='server-export'||name==='export-evidence'){run(async()=>download('sentineldrift-server-evidence.json',JSON.stringify(await api('export'),null,2)));return}if(name==='server-explain'){run(async()=>{explanation=await api('explain',{prediction_id:state.predictions[0].id})});return}if(['train-reviewed','start-real-canary','promote-real','rollback-real','discard-candidate','reset','clear-history','assess'].includes(name)){toast('Use the server controls. Browser actions are disabled in server mode.');return}browserAction(name)};
 bind=function(){browserBind();if($('live-analysis'))$('live-analysis').onsubmit=e=>{e.preventDefault();const urls=$('live-urls').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);run(async()=>{latestBatch=(await api('analyze',{urls})).predictions;explanation=null})};if($('server-review'))$('server-review').onsubmit=e=>{e.preventDefault();const record={url:$('s-url').value,label:Number($('s-label').value),evidence:$('s-evidence').value,reviewer:$('s-reviewer').value,attested:$('s-attest').checked};run(()=>api('feedback',{records:[record]}))};if($('server-import'))$('server-import').onsubmit=e=>{e.preventDefault();const file=$('s-file').files[0],attested=$('s-import-attest').checked;run(async()=>{if(!file||file.size>1048576)throw Error('Choose a CSV smaller than 1 MB');const rows=parseCSV((await file.text()).replace(/^\uFEFF/,'')),headers=rows.shift().map(h=>h.trim().toLowerCase());if(['url','label','evidence','reviewer'].some(h=>!headers.includes(h))||new Set(headers).size!==headers.length)throw Error('CSV needs unique required headers');const records=rows.map(row=>{if(row.length!==headers.length)throw Error('CSV column count mismatch');const r=Object.fromEntries(headers.map((h,i)=>[h,row[i]]));if(!['0','1'].includes(r.label))throw Error('Labels must be 0 or 1');return {...r,label:Number(r.label),attested}});await api('feedback',{records})})};if($('server-policy'))$('server-policy').onsubmit=e=>{e.preventDefault();const policy={threshold:Number($('s-threshold').value)/100,canary:Number($('s-share').value),cooldown:Number($('s-cooldown').value),enabled:$('s-enabled').checked,auto:$('s-auto').checked};run(()=>api('settings',policy,'PUT'))}};
 document.querySelector('.agent').innerHTML='Persistent backend<small>SQLite history · real API serving</small>';
 document.querySelector('.notice').innerHTML='<span>◈</span><span><strong>Server workspace.</strong> Predictions and reviewed feedback persist on this computer. Lower URL risk does not verify identity or guarantee safety.</span>';
 document.querySelector('footer').innerHTML='<span>SentinelDrift / Persistent MLOps prototype</span><span>FastAPI · SQLite · v0.5</span>';
 document.querySelector('.header-right .pill').textContent='● Persistent server';
 await run(async()=>{});
 setInterval(async()=>{if(!working&&!document.querySelector('form:focus-within'))try{await sync();render()}catch(e){serverError='Server unavailable: '+e.message;document.querySelector('.header-right .pill').textContent='● Server unavailable';render()}},15000);
})();
